import java.util.*;

public class textdocumentanalysis {
    static int insideTotal = 0;

    static int countWords(String value) {
        String normalized = value.replace('_', ' ').trim().replaceAll(" +", " ");
        if (normalized.isEmpty()) return 0;
        return normalized.split(" ").length;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        String s = input.next();
        List<Integer> bracePositions = new ArrayList<>();
        bracePositions.add(-1);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == ')') bracePositions.add(i);
        }
        StringBuilder outside = new StringBuilder();
        int maxLength = 0;
        for (int i = 1; i + 1 < bracePositions.size(); i += 2) {
            int left = bracePositions.get(i);
            int right = bracePositions.get(i + 1);
            insideTotal += countWords(s.substring(left + 1, right));
            outside.append('_').append(s, bracePositions.get(i - 1) + 1, left);
        }
        outside.append('_').append(s.substring(bracePositions.get(bracePositions.size() - 1) + 1));
        String outsideWords = outside.toString().replace('_', ' ').trim().replaceAll(" +", " ");
        if (!outsideWords.isEmpty()) {
            for (String word : outsideWords.split(" ")) {
                if (word.length() > maxLength) maxLength = word.length();
            }
        }
        System.out.print(maxLength + " " + insideTotal);
    }
}
